'use client';
import {useState} from 'react';
import s from './TableExample.module.css';
export default function TableExample({variant='standard'}:{variant?:string}){
 const [sort,setSort]=useState(false),[query,setQuery]=useState('');
 const rows=[{name:'Olivia Rhye',email:'olivia@acme.co',status:'Active',role:'Designer',initials:'OR'},{name:'Phoenix Baker',email:'phoenix@acme.co',status:'Invited',role:'Developer',initials:'PB'},{name:'Lana Steiner',email:'lana@acme.co',status:'Active',role:'Manager',initials:'LS'}].filter(row=>(row.name+' '+row.email).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort?a.name.localeCompare(b.name):0);
 return <section className={`${s.demo} ${s.tableShell} ${s[variant]}`}><header className={s.tableHeader}><div><h3>Team members <span>3</span></h3><p>Manage your team and their access.</p></div><label className={s.searchBox}><span className={s.srOnly}>Search team</span><input placeholder="Search members…" value={query} onChange={event=>setQuery(event.target.value)}/></label></header><div className={s.scroll}><table className={s.table}><thead><tr><th scope="col" aria-sort={sort?'ascending':'none'}><button className={s.sort} onClick={()=>setSort(!sort)}>Name {sort?'↑':'↕'}</button></th><th scope="col">Status</th><th scope="col">Role</th></tr></thead><tbody>{rows.map(row=><tr key={row.email}><td><div className={s.person}><span className={s.avatar}>{row.initials}</span><span><strong>{row.name}</strong><small>{row.email}</small></span></div></td><td><span className={`${s.status} ${row.status==='Active'?s.active:s.pending}`}>{row.status}</span></td><td>{row.role}</td></tr>)}</tbody></table>{!rows.length&&<p className={s.noResults}>No members match your search.</p>}</div><footer className={s.tableFooter}>{rows.length} of 3 members<span>Workspace team</span></footer></section>
}

