mix(in srgb,var(--accent) 10%,var(--surface)));border-color:transparent;color:var(--primary)}.ghost{background:transparent;border-color:transparent;color:var(--primary)}.filled{background:linear-gradient(120deg,color-mix(in srgb,var(--primary) 12%,var(--muted)),color-mix(in srgb,var(--accent) 9%,var(--muted)));border-color:transparent}.underlined{border:0;border-bottom:2px solid var(--primary);border-radius:0;background:transparent}.floating{box-shadow:var(--shadow);border-color:transparent}.pill{border-radius:100px}.compact{font-size:.85em}.spacious{padding:24px}.error{color:#ca4b60}.success{color:var(--accent)}.inline{display:flex;gap:15px;align-items:center;flex-wrap:wrap}.center{text-align:center}.circle{border-radius:50%}.separator{height:1px;background:var(--border);border:0;margin:14px 0}.selected{border-color:var(--primary);background:linear-gradient(120deg,color-mix(in srgb,var(--primary) 10%,var(--surface)),color-mix(in srgb,var(--accent) 10%,var(--surface)));color:var(--primary)}@media(prefers-reduced-motion:reduce){.demo *{animation:none!important;transition:none!important}}
