urface)));padding:24px;border-radius:12px}.elevated.elevated{border:var(--border-width,1px) solid var(--border);border-radius:12px;box-shadow:var(--shadow);background:linear-gradient(120deg,color-mix(in srgb,var(--primary) 8%,var(--surface)),color-mix(in srgb,var(--accent) 6%,var(--surface)))}.framed.framed{border:var(--border-width,1px) solid var(--border);border-left:3px solid var(--primary);border-radius:6px;background:linear-gradient(120deg,color-mix(in srgb,var(--primary) 8%,var(--surface)),color-mix(in srgb,var(--accent) 6%,var(--surface)))}.demo :focus-visible{outline:2px solid var(--primary);outline-offset:3px}

/* White layout surfaces */.panel.panel{background:var(--design-surface,var(--surface));color:var(--text);box-shadow:var(--design-shadow,var(--shadow));backdrop-filter:var(--design-blur,none);-webkit-backdrop-filter:var(--design-blur,none);border-color:var(--border);}.demo{font-family:var(--font);font-size:var(--size);line-height:var(--line-height);font-weight:var(--font-weight)}.demo .panel{padding:var(--space)}.demo .button:not(.pill):not(.circle),.demo .input,.demo .panel{border-radius:var(--radius);border-width:var(--border-width,1px)}.demo .button:not(.ghost):not(.outline){box-shadow:var(--design-shadow,var(--shadow))}.demo .input{box-shadow:var(--design-input-shadow,none)}/* End white layout surfaces */

