urface)));padding:24px;border-radius:12px}.elevated.elevated{border:var(--border-width,1px) solid var(--border);border-radius:12px;box-shadow:var(--shadow);background:linear-gradient(120deg,color-mix(in srgb,var(--primary) 8%,var(--surface)),color-mix(in srgb,var(--accent) 6%,var(--surface)))}.framed.framed{border:var(--border-width,1px) solid var(--border);border-left:3px solid var(--primary);border-radius:6px;background:linear-gradient(120deg,color-mix(in srgb,var(--primary) 8%,var(--surface)),color-mix(in srgb,var(--accent) 6%,var(--surface)))}.demo :focus-visible{outline:2px solid var(--primary);outline-offset:3px}

