'use client';
import {useState,useRef,useEffect,useId} from 'react';
import s from './ChartsExample.module.css';
export default function ChartsExample({variant='line'}:{variant?:string}){
const [period,setPeriod]=useState('Month');const values=period==='Month'?[30,48,40,65,52,80,72]:[18,32,24,49,37,58,66];const points=values.map((v,i)=>`${20+i*43},${115-v}`).join(' ');return <div className={`${s.demo} ${s.stack}`}><div className={s.row} style={{justifyContent:'space-between'}}><strong style={{fontSize:12}}>Revenue trend</strong><button className={s.button} style={{padding:'4px 8px',fontSize:10}} onClick={()=>setPeriod(period==='Month'?'Week':'Month')}>{period} ⌄</button></div><svg viewBox="0 0 300 145" role="img" aria-label={period+' sample revenue chart'} className={s.chart}>{[35,75,115].map(y=><line key={y} x1="12" x2="290" y1={y} y2={y} stroke="var(--border)"/>)}{variant==='bar'?values.map((v,i)=><rect key={i} x={12+i*41} y={115-v} width="22" height={v} rx="4" fill="var(--primary)"><title>{v+' thousand rupees'}</title></rect>):<>{variant==='area'&&<polygon points={`20,115 ${points} 278,115`} fill="var(--primary)" opacity=".13"/>}<polyline points={points} fill="none" stroke="var(--primary)" strokeWidth="3" strokeLinejoin="round"/>{values.map((v,i)=><circle key={i} cx={20+i*43} cy={115-v} r="3" fill="var(--primary)"><title>{v+' thousand rupees'}</title></circle>)}</>}<text x="12" y="140" fill="var(--secondary)" fontSize="9">Start of {period.toLowerCase()}</text><text x="270" y="140" fill="var(--secondary)" fontSize="9">Now</text></svg><span className={s.muted}>Illustrative sample data · ₹ thousands</span></div>;
