'use client';
import {useState,useRef,useEffect,useId} from 'react';
import s from './CalendarExample.module.css';
export default function CalendarExample({variant='standard'}:{variant?:string}){
const [month,setMonth]=useState(9);const [year,setYear]=useState(2026);const [chosen,setChosen]=useState('');const days=new Date(year,month+1,0).getDate();const offset=(new Date(year,month,1).getDay()+6)%7;function move(delta:number){const date=new Date(year,month+delta,1);setYear(date.getFullYear());setMonth(date.getMonth())}return <div className={`${s.demo} ${variant==='bordered'?s.panel:variant==='soft'?s.soft:''}`} style={{padding:12,borderRadius:'var(--radius)'}}><div className={s.row} style={{justifyContent:'space-between',marginBottom:15}}><button className={s.arrow} aria-label="Previous month" onClick={()=>move(-1)}>‹</button><strong style={{fontSize:12}}>{new Date(year,month,1).toLocaleString('en-US',{month:'long'})} {year}</strong><button className={s.arrow} aria-label="Next month" onClick={()=>move(1)}>›</button></div><div className={s.calendar}>{['M','T','W','T','F','S','S'].map((d,i)=><span className={s.weekday} key={i}>{d}</span>)}{Array.from({length:offset},(_,i)=><span key={'blank'+i}/>)}{Array.from({length:days},(_,i)=>{const date=`${year}-${String(month+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`;return <button key={date} aria-label={'Select '+date} aria-pressed={chosen===date} className={chosen===date?s.selected:''} onClick={()=>setChosen(date)}>{i+1}</button>})}</div><p className={s.muted} role="status">{chosen?'Selected: '+chosen:'Choose a date'}</p></div>;
}

