'use client';
import {useState,useRef} from 'react';
import s from './DataGridExample.module.css';
export default function DataGridExample({variant='standard'}:{variant?:string}){const [query,setQuery]=useState(''),[sort,setSort]=useState(false);const rows=[{name:'Design system',owner:'Alex',status:'Active'},{name:'Storefront',owner:'Olivia',status:'Pending'},{name:'Mobile app',owner:'Noah',status:'Active'}].filter(x=>(x.name+' '+x.owner).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort?a.name.localeCompare(b.name):0);return <div className={[s.demo,s.panel,s[variant]].join(' ')}><label className={s.label}>Search grid<input className={s.input} value={query} onChange={e=>setQuery(e.target.value)}/></label><button className={s.button} onClick={()=>setSort(!sort)}>Sort by project</button><div className={s.scroll}><table className={s.table}><thead><tr><th scope="col">Project</th><th scope="col">Owner</th><th scope="col">Status</th></tr></thead><tbody>{rows.map(x=><tr key={x.name}><td>{x.name}</td><td>{x.owner}</td><td>{x.status}</td></tr>)}</tbody></table></div>{!rows.length&&<p role="status">No matching projects.</p>}</div>}

