9%,var(--muted)))}.pill{border-radius:30px}.tag{display:inline-flex;gap:8px;align-items:center;background:linear-gradient(120deg,color-mix(in srgb,var(--primary) 12%,var(--muted)),color-mix(in srgb,var(--accent) 9%,var(--muted)));padding:6px 10px;border-radius:var(--radius)}.tag button{border:0;background:none;color:var(--primary);cursor:pointer}.message{background:linear-gradient(120deg,color-mix(in srgb,var(--primary) 12%,var(--muted)),color-mix(in srgb,var(--accent) 9%,var(--muted)));padding:12px;border-radius:var(--radius);margin:10px 0}.bubbles .message{border-radius:30px}.compact .message{padding:6px}.notice{padding:12px;border-bottom:1px solid var(--border)}.menu{position:relative}.menu summary{padding:10px;cursor:pointer;border:1px solid var(--border);border-radius:var(--radius)}.menu[open]>div{position:absolute;top:100%;right:0;z-index:2;display:grid;padding:12px;background:linear-gradient(120deg,color-mix(in srgb,var(--primary) 8%,var(--surface)),color-mix(in srgb,var(--accent) 6%,var(--surface)));border:1px solid var(--border);min-width:180px}.demo :focus-visible{outline:2px solid var(--primary);outline-offset:3px}@media(max-width:600px){.split{grid-template-columns:1fr}}
