'use client';
import {useState,useRef} from 'react';
import {useForm} from 'react-hook-form';import {z} from 'zod';import {zodResolver} from '@hookform/resolvers/zod';
import s from './RegisterFormExample.module.css';
const schema=z.object({name:z.string().min(2).max(80),email:z.string().email(),password:z.string().min(10).regex(/[A-Z]/).regex(/[0-9]/),confirm:z.string().min(2).max(80)}).refine(x=>x.password===x.confirm,{message:'Passwords do not match',path:['confirm']});const fields=["name","email","password","confirm"] as const;export default function RegisterFormExample({variant='standard'}:{variant?:string}){const [success,setSuccess]=useState(false);const {register,handleSubmit,formState:{errors,isSubmitting}}=useForm<z.infer<typeof schema>>({resolver:zodResolver(schema)});return <div className={[s.demo,s.panel,s[variant]].join(' ')}><h3>Registration forms</h3><form noValidate onSubmit={handleSubmit(async()=>{setSuccess(true)})}>{fields.map(key=><label className={s.label} key={key}>{key}<input className={s.input} {...register(key)} type={key==='email'?'email':['password','confirm'].includes(key)?'password':'text'} aria-invalid={!!errors[key]}/>{errors[key]&&<small className={s.error} role="alert">{errors[key]?.message}</small>}</label>)}<button className={s.button} disabled={isSubmitting}>{isSubmitting?'Validating…':'Save example'}</button></form><p className={s.muted} role="status">{success?'Example validated successfully.':'Local validation example · use sample details only.'}</p></div>}

