'use client';
import {useState,useRef} from 'react';
import {useForm} from 'react-hook-form';import {z} from 'zod';import {zodResolver} from '@hookform/resolvers/zod';
import s from './SettingsFormExample.module.css';
const schema=z.object({name:z.string().min(2).max(80),email:z.string().email(),timezone:z.string().min(2).max(80)});const fields=["name","email","timezone"] as const;export default function SettingsFormExample({variant='standard'}:{variant?:string}){const [success,setSuccess]=useState(false);const {register,handleSubmit,formState:{errors,isSubmitting}}=useForm<z.infer<typeof schema>>({resolver:zodResolver(schema)});return <div className={[s.demo,s.panel,s[variant]].join(' ')}><h3>Settings forms</h3><form noValidate onSubmit={handleSubmit(async()=>{setSuccess(true)})}>{fields.map(key=><label className={s.label} key={key}>{key}<input className={s.input} {...register(key)} type={key==='email'?'email':['password','confirm'].includes(key)?'password':'text'} aria-invalid={!!errors[key]}/>{errors[key]&&<small className={s.error} role="alert">{errors[key]?.message}</small>}</label>)}<button className={s.button} disabled={isSubmitting}>{isSubmitting?'Validating…':'Save example'}</button></form><p className={s.muted} role="status">{success?'Example validated successfully.':'Local validation example · use sample details only.'}</p></div>}

